def solve(weights, values, capacity):
    """0/1 knapsack: maximum total value without exceeding capacity.
    weights and values are lists of equal length. Use DP with O(capacity) memory.
    """
    n = len(weights)
    dp = [0] * (capacity + 1)
    for i in range(n):
        w = weights[i]
        v = values[i]
        if w > capacity:
            continue
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity]

