def solve(matrix):
    """Return the determinant of a square integer matrix.
    Handles any size using exact Gaussian elimination with Fractions.
    An empty matrix has determinant 1.
    Non-square matrices return 0.
    """
    from fractions import Fraction
    n = len(matrix)
    if n == 0:
        return 1
    # verify square
    for row in matrix:
        if len(row) != n:
            return 0
    # copy as Fractions
    A = [[Fraction(val) for val in row] for row in matrix]
    det = Fraction(1)
    sign = 1
    for i in range(n):
        # find pivot
        pivot_row = None
        for r in range(i, n):
            if A[r][i] != 0:
                pivot_row = r
                break
        if pivot_row is None:
            return 0
        if pivot_row != i:
            A[i], A[pivot_row] = A[pivot_row], A[i]
            sign *= -1
        pivot = A[i][i]
        det *= pivot
        # eliminate below
        for r in range(i+1, n):
            factor = A[r][i] / pivot
            if factor == 0:
                continue
            for c in range(i, n):
                A[r][c] -= factor * A[i][c]
    result = sign * det
    return int(result)

