def solve(path: str) -> str:
    """Simplify an absolute Unix path.
    Handles '.' (current directory), '..' (parent directory), duplicate slashes,
    and removes any trailing slash. Returns '/' for empty or root paths.
    """
    # If the input is empty, treat it as root.
    if not path:
        return '/'
    # Split the path into components.
    parts = path.split('/')
    stack: list[str] = []
    for part in parts:
        # Skip empty components (caused by '//' or leading slash) and current dir.
        if part == '' or part == '.':
            continue
        if part == '..':
            # Go up one directory if possible.
            if stack:
                stack.pop()
            # If already at root, stay there.
        else:
            # Normal directory name.
            stack.append(part)
    # Build the simplified path; '/' + join of stack (empty stack yields '/').
    return '/' + '/'.join(stack)

