def solve(meetings):
    """Return the maximum number of non‑overlapping meetings.
    Each meeting is expected to be an iterable with at least two numeric elements
    representing ``start`` and ``end``. Meetings with ``start > end`` or malformed
    entries are ignored. A meeting may start exactly when another ends.
    """
    if not meetings:
        return 0
    # Extract valid (start, end) pairs
    valid = []
    for m in meetings:
        try:
            start, end = m[0], m[1]
        except Exception:
            continue
        # Ensure comparable numbers
        if not (isinstance(start, (int, float)) and isinstance(end, (int, float))):
            continue
        if start <= end:
            valid.append((start, end))
    if not valid:
        return 0
    # Sort by end time, then start time for determinism
    valid.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -float('inf')
    for start, end in valid:
        if start >= current_end:
            count += 1
