    If the path starts with '/', it is treated as absolute and the result also starts with '/'.
    Otherwise it is treated as relative and the result does not start with a leading slash.
    The function resolves '.' and '..', collapses multiple slashes and removes any trailing slash.
    """
    if not path:
        # Empty path – return empty string (no components)
        return ''
    is_abs = path.startswith('/')
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            # Skip empty components (multiple slashes) and current directory.
            continue
        if part == '..':
            if stack:
                stack.pop()
            else:
                # If relative and nothing to go back to, keep the '..'
                if not is_abs:
                    stack.append('..')
            # If absolute and stack empty, stay at root (ignore extra '..')
        else:
            stack.append(part)
    # Build the result
    if is_abs:
        return '/' + '/'.join(stack)
    else:
        return '/'.join(stack)

