    valid = []
    for m in meetings:
        try:
            start, end = m[0], m[1]
        except Exception:
            continue
        if not isinstance(start, (int, float)) or not isinstance(end, (int, float)):
            continue
        if start <= end:
            valid.append((start, end))
    if not valid:
        return 0
    # Sort by end time, then start time for deterministic selection
    valid.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -float('inf')
