    """Evaluate Reverse Polish Notation.
    Supports +, -, *, / operators. Division truncates toward zero.
    If division by zero occurs, the result is defined as 0.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:  # division
                if b == 0:
