def solve(tokens):
    """Evaluate Reverse Polish Notation.
    Supports +, -, *, / operators. Division truncates toward zero.
    If division by zero occurs, the result is defined as 0.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:  # division
                if b == 0:
                    stack.append(0)
                else:
                    # Truncate toward zero without using floating point
                    sign = -1 if (a * b) < 0 else 1
                    stack.append(sign * (abs(a) // abs(b)))
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

